#!/usr/bin/env python3
"""Real session socket and background loop; synthetic audio/hardware state."""
from pathlib import Path
import os,subprocess,tempfile
r=Path(__file__).resolve().parents[1];q=r/'.cache/soundcloud-qa';q.mkdir(parents=True,exist_ok=True);h=q/'include';s=r/'upstream/src'
code='#include "nxt_session.c"\n#include "background.c"\n#include <assert.h>\n#include <errno.h>\n#include <sys/wait.h>\nNxtConfig nxt;\nstatic bool soundcloud_active=true,stopping;\nstatic int ticks,prepared,recovered,quit_sc,peer=-1,server_pair=-1;static bool pending_accept;\nbool NxtSoundCloud_active(void){return soundcloud_active;}\nbool NxtSoundCloud_hasMetadata(void){return soundcloud_active;}\nbool NxtSoundCloud_isPlaying(void){return soundcloud_active;}\nint NxtSoundCloud_position(void){return ticks*20;}\nconst char *NxtSoundCloud_uri(void){return "soundcloud:tracks:1";}\nconst TrackInfo *NxtSoundCloud_info(void){static TrackInfo info={.codec="AAC"};return &info;}\nvoid NxtSoundCloud_quit(void){soundcloud_active=false;quit_sc++;}\nbool PlayerModule_isActive(void){return false;}\nvoid PlayerModule_backgroundTick(void){}\nbool Radio_isActive(void){return false;}\nbool Podcast_isActive(void){return false;}\nvoid Radio_stop(void){}\nvoid Podcast_stop(void){}\nvoid Podcast_flushProgress(void){}\nvoid PodcastModule_backgroundTick(void){}\nvoid Player_stop(void){}\nPlayerState Player_getState(void){return PLAYER_STATE_STOPPED;}\nint Player_getPosition(void){return 0;}\nconst TrackInfo *Player_getTrackInfo(void){static TrackInfo i;return &i;}\nconst char *Player_getCurrentFile(void){return "";}\nvoid Resume_updatePosition(int ms){assert(0);}\nvoid MusicPlaying_leave(void){}\nvoid Spectrum_quit(void){}\nvoid DisplayHelper_prepareForExternal(void){prepared++;}\nvoid DisplayHelper_recoverDisplay(void){recovered++;}\nvoid PAD_quit(void){}\nvoid PAD_init(void){}\nvoid PAD_reset(void){}\nvoid ModuleCommon_init(void){}\nvoid ModuleCommon_setAutosleepDisabled(bool v){}\nbool ModuleCommon_stopSignalled(void){return stopping;}\nint __wrap_socket(int domain,int type,int protocol){int pair[2];assert(!socketpair(AF_UNIX,SOCK_STREAM,0,pair));server_pair=pair[0];peer=pair[1];return pair[0];}\nint __wrap_bind(int fd,const struct sockaddr *address,socklen_t length){return 0;}\nint __wrap_listen(int fd,int backlog){return 0;}\nint __wrap_accept(int fd,struct sockaddr *address,socklen_t *length){if(pending_accept){pending_accept=false;return dup(server_pair);}errno=EAGAIN;return -1;}\nvoid Nxt_tick(void){ticks++;char reply[1200]={0};if(ticks==2){assert(send(peer,"STATUS\\n",7,0)==7);pending_accept=true;}if(ticks==3){assert(read(peer,reply,sizeof(reply)-1)>0);assert(strstr(reply,"HIDDEN")&&strstr(reply,"AAC")&&strstr(reply,"soundcloud:tracks:"));assert(send(peer,"ATTACH\\n",7,0)==7);pending_accept=true;}if(ticks==4){assert(read(peer,reply,sizeof(reply)-1)>0&&!strcmp(reply,"OK\\n"));}}\nstatic void request_client(const char *request,bool check_status){int fd=socket(AF_UNIX,SOCK_STREAM,0);struct sockaddr_un a={.sun_family=AF_UNIX};strcpy(a.sun_path,socket_path);assert(!connect(fd,(struct sockaddr*)&a,sizeof(a)));assert(send(fd,request,strlen(request),0)>0);char reply[1200]={0};assert(read(fd,reply,sizeof(reply)-1)>0);if(check_status){assert(strstr(reply,"HIDDEN")&&strstr(reply,"AAC")&&strstr(reply,"soundcloud:tracks:"));}else assert(!strcmp(reply,"OK\\n"));close(fd);}\nint main(int argc,char **argv){\n nxt.background=1;char *args[]={"qa","--session"};assert(!NxtSession_start(2,args));\n assert(NxtSession_background(NULL));\n assert(soundcloud_active&&ticks>=4&&prepared==1&&recovered==1&&Background_getActive()==BG_SOUNDCLOUD&&!NxtSession_isHidden());\n stopping=true;assert(!NxtSession_background(NULL)&&soundcloud_active);stopping=false;\n Background_stopAll();assert(!soundcloud_active&&quit_sc==1&&Background_getActive()==BG_NONE);assert(!NxtSession_background(NULL));NxtSession_quit();return 0;\n}'
code='#include "'+str(r/'qa/spotify_stub.inc')+'"\n'+code
f=q/'test_background_native.c';f.write_text(code)
incs=['-I'+str(h),'-I'+str(s),'-I'+str(s/'include'),'-I'+str(r/'upstream/NextUI/workspace/all/common'),'-I'+str(r/'upstream/NextUI/workspace/tg5040/platform'),'-I'+str(r/'upstream/NextUI/workspace/tg5040/libmsettings')]
subprocess.run(['gcc','-O2','-D_GNU_SOURCE','-DUSE_SDL2','-ffunction-sections','-fdata-sections',*incs,str(f),'-Wl,--gc-sections,--wrap=socket,--wrap=bind,--wrap=listen,--wrap=accept','-o',str(q/'background')],check=True)
with tempfile.TemporaryDirectory() as td:subprocess.run([str(q/'background')],env={**os.environ,'NXT_SESSION_SOCKET':td+'/session.sock'},check=True,timeout=5)
print('PASS production detached SoundCloud session: socketpair transport (host blocks bind/listen), hidden STATUS includes SoundCloud, tick continues, ATTACH restores UI and same active player, logo-stop blocks detach, stop-all closes SoundCloud; simulated display/audio hardware.')
